// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title KipuBankV2
 * @notice Versión mejorada de KipuBank con:
 *  - Control de acceso (AccessControl de OpenZeppelin)
 *  - Multi-token (ERC20) + ETH (address(0))
 *  - Oráculos Chainlink por token (price feeds)
 *  - Contabilidad interna en "USDC decimals" (6)
 *  - Eventos y errores personalizados
 *  - Patrones de seguridad: reentrancy, checks-effects-interactions, SafeERC20
 */

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

interface AggregatorV3Interface {
    function decimals() external view returns (uint8);
    function latestRoundData() external view returns (
        uint80 roundId,
        int256 answer,
        uint256 startedAt,
        uint256 updatedAt,
        uint80 answeredInRound
    );
}

contract KipuBankV2 is AccessControl, ReentrancyGuard {
    using SafeERC20 for IERC20;

    /* ========== ROLES ========== */
    bytes32 public constant MANAGER_ROLE = keccak256("MANAGER_ROLE");

    /* ========== CONSTANTS ========== */
    uint8 public constant USDC_DECIMALS = 6; // internal accounting in USDC decimals

    /* ========== CUSTOM ERRORS ========== */
    error Err_NotSupportedToken(address token);
    error Err_InvalidAmount();
    error Err_InsufficientBalance(address user, address token, uint256 requested, uint256 available);
    error Err_BankCapExceeded(uint256 attemptedUsd, uint256 capUsd);
    error Err_NotManager();
    error Err_PriceQueryFailed(address token);

    /* ========== EVENTS ========== */
    event TokenRegistered(address indexed token, address indexed priceFeed, uint8 tokenDecimals);
    event TokenUnregistered(address indexed token);
    event Deposit(address indexed user, address indexed token, uint256 amount, uint256 usdValue);
    event Withdraw(address indexed user, address indexed token, uint256 amount, uint256 usdValue);
    event BankCapUpdated(uint256 oldCapUsd, uint256 newCapUsd);

    /* ========== STORAGE ========== */

    // balances[token][user] = amount (token native units)
    mapping(address => mapping(address => uint256)) public balances;

    // token -> price feed aggregator (Chainlink)
    mapping(address => AggregatorV3Interface) public priceFeeds;

    // token -> token decimals (e.g. 18 for ETH/ERC20, 6 for USDC)
    mapping(address => uint8) public tokenDecimals;

    // Supported tokens set (simple mapping)
    mapping(address => bool) public supportedToken;

    // Bank cap in USD using USDC_DECIMALS (e.g. $1_000 => 1_000 * 10**6)
    uint256 public bankCapUsd;

    // Track approximate total deposits in USD (in USDC_DECIMALS). Updated at deposit/withdraw.
    uint256 public totalDepositedUsd;

    /* ========== CONSTRUCTOR ========== */
    constructor(uint256 initialBankCapUsd) {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(MANAGER_ROLE, msg.sender);

        bankCapUsd = initialBankCapUsd;
    }

    /* ========== MODIFIERS ========== */
    modifier onlyManager() {
        if (!hasRole(MANAGER_ROLE, msg.sender)) revert Err_NotManager();
        _;
    }

    /* ========== ADMIN FUNCTIONS ========== */

    /// @notice Register a token and its Chainlink price feed + decimals
    function registerToken(address token, address priceFeed, uint8 _tokenDecimals) external onlyManager {
        require(token != address(0) || priceFeed != address(0), "Must provide token or feed");
        priceFeeds[token] = AggregatorV3Interface(priceFeed);
        tokenDecimals[token] = _tokenDecimals;
        supportedToken[token] = true;
        emit TokenRegistered(token, priceFeed, _tokenDecimals);
    }

    /// @notice Unregister a token
    function unregisterToken(address token) external onlyManager {
        supportedToken[token] = false;
        delete priceFeeds[token];
        delete tokenDecimals[token];
        emit TokenUnregistered(token);
    }

    /// @notice Update bank cap (value in USDC_DECIMALS)
    function updateBankCap(uint256 newCapUsd) external onlyManager {
        uint256 old = bankCapUsd;
        bankCapUsd = newCapUsd;
        emit BankCapUpdated(old, newCapUsd);
    }

    /* ========== DEPOSIT / WITHDRAWAL ========== */

    /// @notice Deposit ERC20 token
    function depositERC20(address token, uint256 amount) external nonReentrant {
        if (!supportedToken[token]) revert Err_NotSupportedToken(token);
        if (amount == 0) revert Err_InvalidAmount();

        // transfer tokens in
        IERC20(token).safeTransferFrom(msg.sender, address(this), amount);

        // compute USD value (in USDC decimals)
        uint256 usdValue = _tokenToUsd(token, amount);

        // enforce bank cap
        if (totalDepositedUsd + usdValue > bankCapUsd) revert Err_BankCapExceeded(usdValue, bankCapUsd);

        // effects
        balances[token][msg.sender] += amount;
        totalDepositedUsd += usdValue;

        emit Deposit(msg.sender, token, amount, usdValue);
    }

    /// @notice Deposit native ETH (use token == address(0))
    function depositETH() external payable nonReentrant {
        address token = address(0);
        if (!supportedToken[token]) revert Err_NotSupportedToken(token);
        if (msg.value == 0) revert Err_InvalidAmount();

        uint256 usdValue = _tokenToUsd(token, msg.value);
        if (totalDepositedUsd + usdValue > bankCapUsd) revert Err_BankCapExceeded(usdValue, bankCapUsd);

        balances[token][msg.sender] += msg.value;
        totalDepositedUsd += usdValue;

        emit Deposit(msg.sender, token, msg.value, usdValue);
    }

    /// @notice Withdraw token
    function withdraw(address token, uint256 amount) external nonReentrant {
        uint256 userBal = balances[token][msg.sender];
        if (amount == 0) revert Err_InvalidAmount();
        if (amount > userBal) revert Err_InsufficientBalance(msg.sender, token, amount, userBal);

        // compute USD value for accounting (note: uses current price)
        uint256 usdValue = _tokenToUsd(token, amount);

        // effects
        balances[token][msg.sender] = userBal - amount;
        if (totalDepositedUsd >= usdValue) {
            totalDepositedUsd -= usdValue;
        } else {
            // small drift protection
            totalDepositedUsd = 0;
        }

        // interactions (checks-effects-interactions)
        if (token == address(0)) {
            // ETH
            (bool ok, ) = payable(msg.sender).call{value: amount}("");
            require(ok, "ETH transfer failed");
        } else {
            IERC20(token).safeTransfer(msg.sender, amount);
        }

        emit Withdraw(msg.sender, token, amount, usdValue);
    }

    /* ========== VIEW HELPERS ========== */

    /// @notice Returns USD value (in USDC_DECIMALS) for token amount using its priceFeed
    function tokenToUsdView(address token, uint256 amount) external view returns (uint256) {
        return _tokenToUsd(token, amount);
    }

    /// @notice Get price feed decimals for a token (if registered)
    function priceFeedDecimals(address token) external view returns (uint8) {
        AggregatorV3Interface feed = priceFeeds[token];
        if (address(feed) == address(0)) return 0;
        return feed.decimals();
    }

    /* ========== INTERNALS ========== */

    function _tokenToUsd(address token, uint256 amount) internal view returns (uint256) {
        AggregatorV3Interface feed = priceFeeds[token];
        if (address(feed) == address(0)) revert Err_PriceQueryFailed(token);

        (, int256 answer, , uint256 updatedAt, ) = feed.latestRoundData();
        // conservative: check update timestamp > 0
        if (answer <= 0 || updatedAt == 0) revert Err_PriceQueryFailed(token);

        uint8 feedDecimals = feed.decimals();         // e.g. 8
        uint8 tDecimals = tokenDecimals[token];       // e.g. 18 or 6
        // Convert: amount * price * (10**USDC_DECIMALS) / (10**tDecimals * 10**feedDecimals)

        // Use uint256 math carefully:
        uint256 uAmount = amount;
        uint256 uPrice = uint256(answer);

        // numerator: amount * price * 10**USDC_DECIMALS
        // To avoid overflow in extreme cases, reorder: (amount / 1e? ) * ... but since solidity 0.8 and typical ranges, this is acceptable for course purposes.
        uint256 numerator = uAmount * uPrice * (10 ** USDC_DECIMALS);

        uint256 denom = (10 ** uint256(tDecimals)) * (10 ** uint256(feedDecimals));
        return numerator / denom;
    }

    /* ========== FALLBACK / RECEIVE ========== */

    receive() external payable {
        // Accept ETH only when token address(0) is registered and user calls depositETH
        // For safety, fallback direct sends to revert unless address(0) supported (we don't revert here to avoid losing funds),
        // but we prefer explicit depositETH(). This receive is minimal.
    }
}

